  photoBase64 = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";
}

// 3. Bersihkan prefix Base64
const cleanBase64 = photoBase64.replace(/^data:image\/\w+;base64,/, '');
const doNumber = $input.item.json.do_number || 'SJ-2026';

// 4. Return data JSON + binary data untuk Google Drive
return {
  json: $input.item.json,
  binary: {
    data: {
      data: cleanBase64,
      mimeType: "image/png",
      fileName: `POD_${doNumber}_${Date.now()}.png`
    }
  }
};

